        Mood.HAPPY -> R.drawable.mascot_cat_happy
        Mood.CONTENT -> R.drawable.mascot_cat_content
        Mood.CALM -> R.drawable.mascot_cat_calm
        Mood.WORRIED -> R.drawable.mascot_cat_worried
        Mood.UPSET -> R.drawable.mascot_cat_upset
        Mood.UNWELL -> R.drawable.mascot_cat_unwell
